// THE BUNDLED SCENES, READ FROM DISK (the files beside this one, generated by `scripts/themes-bundle.mjs`). Once per
// file, like Len's own skills (`lib/agent/skills/bundled.ts`): `next.config.ts` traces `lib/themes/bundled/*.svg` into
// the standalone build, because nothing here imports them. Only a name that `index.ts` took from its own list gets
// here, so there is no path to build from what somebody typed.
import "server-only";

import fs from "node:fs";
import path from "node:path";

const DIR = path.join(process.cwd(), "lib", "themes", "bundled");

const cache = new Map<string, string>();

/** A scene's SVG, byte for byte. Throws when the file is not there: a bundled theme without its scene is a broken build. */
export function readBundledScene(file: string): string {
  const cached = cache.get(file);
  if (cached !== undefined) return cached;
  const svg = fs.readFileSync(path.join(DIR, file), "utf8");
  cache.set(file, svg);
  return svg;
}
